#[path = "solution.rs"]
mod solution;

use solution::*;

fn close(actual: f64, expected: f64) {
    assert!((actual - expected).abs() <= 1e-12, "actual={actual}, expected={expected}");
}

#[test]
fn empty_samples_return_the_maximum() {
    let grid = CellGrid { cell_width: 2.0 };
    assert_eq!(stable_step(0.75, &grid, &[], &[]), Ok(0.75));
}

#[test]
fn motion_and_deformation_limits_are_combined() {
    let grid = CellGrid { cell_width: 2.0 };
    let samples = vec![BodySample {
        velocity: [3.0, 4.0],
        gradient: [[2.0, 0.0], [0.0, 0.0]],
        damaged: false,
        material: 0,
    }];
    let materials = vec![MaterialRule {
        use_motion_limit: true,
        deformation_limit: Some(0.2),
    }];
    assert_eq!(stable_step(10.0, &grid, &samples, &materials), Ok(0.2));

    let damaged = vec![BodySample { damaged: true, ..samples[0].clone() }];
    close(stable_step(10.0, &grid, &damaged, &materials).unwrap(), 2.0 / 7.0);
}

#[test]
fn zero_motion_denominator_adds_no_limit() {
    let grid = CellGrid { cell_width: 3.0 };
    let samples = [BodySample {
        velocity: [0.0, 0.0],
        gradient: [[0.0, 0.0], [0.0, 0.0]],
        damaged: false,
        material: 0,
    }];
    let materials = [MaterialRule { use_motion_limit: true, deformation_limit: None }];
    assert_eq!(stable_step(1.25, &grid, &samples, &materials), Ok(1.25));
}

#[test]
fn limits_across_samples_take_the_minimum() {
    let grid = CellGrid { cell_width: 1.0 };
    let samples = [
        BodySample { velocity: [2.0, 0.0], gradient: [[0.0; 2]; 2], damaged: true, material: 0 },
        BodySample { velocity: [0.0; 2], gradient: [[0.0; 2]; 2], damaged: false, material: 1 },
    ];
    let materials = [
        MaterialRule { use_motion_limit: true, deformation_limit: Some(0.01) },
        MaterialRule { use_motion_limit: false, deformation_limit: Some(0.3) },
    ];
    assert_eq!(stable_step(5.0, &grid, &samples, &materials), Ok(0.3));
}

#[test]
fn all_inputs_are_validated_before_calculation() {
    let valid_grid = CellGrid { cell_width: 1.0 };
    assert_eq!(stable_step(0.0, &valid_grid, &[], &[]), Err(StepError::InvalidMaximum));
    assert_eq!(stable_step(f64::INFINITY, &valid_grid, &[], &[]), Err(StepError::InvalidMaximum));
    assert_eq!(stable_step(1.0, &CellGrid { cell_width: 0.0 }, &[], &[]), Err(StepError::InvalidGrid));
    assert_eq!(stable_step(1.0, &CellGrid { cell_width: f64::NAN }, &[], &[]), Err(StepError::InvalidGrid));

    let materials = [MaterialRule { use_motion_limit: false, deformation_limit: None }];
    let bad_number = [BodySample {
        velocity: [f64::NAN, 0.0], gradient: [[0.0; 2]; 2], damaged: false, material: 0,
    }];
    assert_eq!(stable_step(1.0, &valid_grid, &bad_number, &materials), Err(StepError::InvalidSample));

    let missing = [BodySample {
        velocity: [0.0; 2], gradient: [[0.0; 2]; 2], damaged: false, material: 1,
    }];
    assert_eq!(stable_step(1.0, &valid_grid, &missing, &materials), Err(StepError::MissingMaterial));

    for limit in [0.0, -1.0, f64::INFINITY, f64::NAN] {
        let rules = [MaterialRule { use_motion_limit: false, deformation_limit: Some(limit) }];
        let sample = [BodySample {
            velocity: [0.0; 2], gradient: [[0.0; 2]; 2], damaged: true, material: 0,
        }];
        assert_eq!(stable_step(1.0, &valid_grid, &sample, &rules), Err(StepError::InvalidLimit));
    }
}

#[test]
fn inputs_are_not_mutated() {
    let grid = CellGrid { cell_width: 2.0 };
    let samples = vec![BodySample {
        velocity: [1.0, 2.0], gradient: [[3.0, 4.0], [5.0, 6.0]], damaged: false, material: 0,
    }];
    let materials = vec![MaterialRule { use_motion_limit: true, deformation_limit: Some(0.4) }];
    let grid_before = grid.clone();
    let samples_before = samples.clone();
    let materials_before = materials.clone();
    let _ = stable_step(2.0, &grid, &samples, &materials);
    assert_eq!(grid, grid_before);
    assert_eq!(samples, samples_before);
    assert_eq!(materials, materials_before);
}

